<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { api } from '@/app/runtime'; import { useAsync } from '@/composables/useAsync'; import type { JsonObject, User } from '@/api/types';
const settings = useAsync<JsonObject>(); const users = useAsync<User[]>(); const userItems = computed(() => users.data.value ?? []); const error = ref(''); const form = reactive({ announcement: '', categories: '' }); onMounted(async () => { const data = await settings.run(() => api.settings.get()); if (data) Object.assign(form, data); void users.run(() => api.users.list()); });
async function save() { error.value = ''; try { await api.settings.save({ announcement: { text: form.announcement }, categories: form.categories.split(',').map((item) => item.trim()).filter(Boolean) }); } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } }
</script>
<template><section class="page"><h1>管理后台</h1><form class="card form" @submit.prevent="save"><label>公告<textarea v-model="form.announcement"></textarea></label><label>展会分类<input v-model="form.categories"></label><p v-if="error" class="error">{{ error }}</p><button class="cta">保存设置</button></form><article class="card"><h2>用户</h2><div v-for="user in userItems" :key="user.id" class="row-card"><span>{{ user.nickname || user.username }}</span><span>{{ user.status }}</span></div></article></section></template>
